import os
import sqlite3
import requests
from langchain.tools import tool

DB_PATH = os.environ.get("SOCIAL_DB", "social.db")
PUBLISH_URLS = {
    "twitter": "https://api.twitter.com/2/tweets",
    "linkedin": "https://api.linkedin.com/v2/ugcPosts",
    "facebook": "https://graph.facebook.com/v19.0/me/feed",
}


def _load_post(post_id):
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT body, media_url, access_token FROM scheduled_posts WHERE id = ?",
            (post_id,),
        ).fetchone()
    finally:
        conn.close()
    return row


@tool
def run_scheduled_post_publisher(post_id: str, platform: str) -> str:
    url = PUBLISH_URLS.get(platform.lower())
    if url is None:
        return f"Unsupported platform: {platform}"
    row = _load_post(post_id)
    if row is None:
        return f"Post {post_id} not found"
    body, media_url, token = row
    payload = {"text": body}
    if media_url:
        payload["media_url"] = media_url
    resp = requests.post(
        url,
        json=payload,
        headers={"Authorization": f"Bearer {token}"},
        timeout=30,
    )
    if resp.status_code >= 400:
        return f"Publish failed: {resp.status_code} {resp.text}"
    return resp.json().get("url", "published")

import os
import json
import sqlite3
from agents import function_tool

DB_PATH = os.environ.get("SOCIAL_DB", "social.db")


def _rate(interactions, impressions):
    if not impressions:
        return 0.0
    return round(100.0 * interactions / impressions, 2)


@function_tool
def summarize_campaign_engagement(
    campaign_id: str, start_date: str, end_date: str, top_n: int = 3
) -> str:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        platform_rows = conn.execute(
            "SELECT platform, SUM(impressions) AS imp, SUM(likes) AS likes, "
            "SUM(comments) AS comments, SUM(shares) AS shares "
            "FROM post_metrics WHERE campaign_id = ? AND metric_date BETWEEN ? AND ? "
            "GROUP BY platform",
            (campaign_id, start_date, end_date),
        ).fetchall()
        top_rows = conn.execute(
            "SELECT post_id, platform, impressions, likes + comments + shares AS total "
            "FROM post_metrics WHERE campaign_id = ? AND metric_date BETWEEN ? AND ? "
            "ORDER BY total DESC LIMIT ?",
            (campaign_id, start_date, end_date, top_n),
        ).fetchall()
    finally:
        conn.close()

    if not platform_rows:
        return json.dumps({"campaign_id": campaign_id, "message": "No metrics found"})

    platforms = []
    for r in platform_rows:
        interactions = (r["likes"] or 0) + (r["comments"] or 0) + (r["shares"] or 0)
        platforms.append(
            {
                "platform": r["platform"],
                "impressions": r["imp"] or 0,
                "interactions": interactions,
                "engagement_rate_pct": _rate(interactions, r["imp"]),
            }
        )
    top_posts = [
        {
            "post_id": t["post_id"],
            "platform": t["platform"],
            "interactions": t["total"],
        }
        for t in top_rows
    ]
    return json.dumps(
        {"campaign_id": campaign_id, "platforms": platforms, "top_posts": top_posts}
    )

import os
import sqlite3

conn = sqlite3.connect(os.environ.get("SOCIAL_DB", "social.db"))


def reschedule_draft_post(post_id: str, new_publish_at: str) -> dict:
    conn.execute(
        "UPDATE scheduled_posts SET publish_at = ?, status = 'scheduled' WHERE id = ?",
        (new_publish_at, post_id),
    )
    conn.commit()
    row = conn.execute(
        "SELECT id, platform, body, publish_at, status FROM scheduled_posts WHERE id = ?",
        (post_id,),
    ).fetchone()
    if row is None:
        return {"error": "post not found"}
    return dict(zip(["id", "platform", "body", "publish_at", "status"], row))

import os
import json
from datetime import datetime, timedelta, timezone
import requests
from langchain.tools import tool

API_BASE = os.environ.get("SOCIAL_API_BASE", "https://api.socialhub.internal/v1")
API_KEY = os.environ.get("SOCIAL_API_KEY", "")


def _parse_ts(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


def _is_unanswered(mention):
    if mention.get("replied"):
        return False
    for reply in mention.get("replies", []):
        if reply.get("author_is_brand"):
            return False
    return True


@tool
def find_unanswered_mentions(account_id: str, max_age_hours: int = 48, limit: int = 20) -> str:
    headers = {"Authorization": f"Bearer {API_KEY}"}
    resp = requests.get(
        f"{API_BASE}/accounts/{account_id}/mentions",
        headers=headers,
        params={"include": "replies", "per_page": 100},
        timeout=30,
    )
    resp.raise_for_status()
    cutoff = datetime.now(timezone.utc) - timedelta(hours=max_age_hours)

    results = []
    for m in resp.json().get("data", []):
        created = _parse_ts(m["created_at"])
        if created < cutoff:
            continue
        if not _is_unanswered(m):
            continue
        results.append(
            {
                "id": m["id"],
                "author": m.get("author_handle"),
                "text": m.get("text", "")[:280],
                "created_at": m["created_at"],
            }
        )
    results.sort(key=lambda x: x["created_at"])
    return json.dumps({"account_id": account_id, "count": len(results[:limit]), "mentions": results[:limit]})
